<?php
declare(strict_types=1);
if(getenv('GITHUB_ACTIONS')!=='true'||getenv('SOKNA_R233_DISPOSABLE_ONLY')!=='YES')throw new RuntimeException('REFUSE_NON_DISPOSABLE_ENVIRONMENT');
$web=realpath((string)getenv('SOKNA_R213_WEB'));$tmp=realpath((string)getenv('RUNNER_TEMP'));
if(!$web||!$tmp||!str_starts_with($web,$tmp.DIRECTORY_SEPARATOR))throw new RuntimeException('REFUSE_OUTSIDE_RUNNER_TEMP');
$configFile=dirname($web).'/config.php';if(!is_file($configFile))throw new RuntimeException('UNINSTALLED');
require_once $web.'/bootstrap.php';$raw=require $configFile;$core=sokna_local_bootstrap($raw);$pdo=$core->database();
$checks=0;$ok=function(bool $yes,string $id)use(&$checks):void{if(!$yes)throw new RuntimeException('FAIL_R233_'.$id);++$checks;echo 'PASS_R233_'.$id."\n";};
$uid=(int)$pdo->query("SELECT id FROM users WHERE role='admin' AND active=1 ORDER BY id LIMIT 1")->fetchColumn();$ok($uid>0,'SETUP_LOCAL_USER');
$actor=['id'=>$uid,'role'=>'admin'];$old=(string)getenv('SOKNA_R213_ADMIN_PASSWORD');
$q=$pdo->prepare('SELECT password_hash FROM users WHERE id=?');$q->execute([$uid]);$ok(password_verify($old,(string)$q->fetchColumn()),'CANONICAL_PASSWORD_OLD_VALID');
$before=$core->adminControls()->snapshot($actor);$ok(($before['settings']['final_amount_rial']??false)===false,'DEFAULT_FINAL_DISPLAY_TOMAN');
$payload=['cafe_name'=>'R233 synthetic cafe','brand_subtitle'=>'R233 QA','business_day_cutoff'=>'04:00','waiter_call_enabled'=>true,'final_amount_rial'=>true];
$core->adminControls()->saveSettings($payload,$actor);
$after=$core->adminControls()->snapshot($actor);$ok(($after['settings']['final_amount_rial']??false)===true,'ENABLE_RIAL_SETTING_STORED');
$s=$pdo->query("SELECT setting_value FROM settings WHERE setting_key='payment.final_amount_rial'")->fetchColumn();$ok((string)$s==='1','RIAL_SETTING_ONE_BYTE');
$projection=$core->publicProjectionBuilder()->remoteModelsFor(['operations']);$ok(count($projection)===1&&isset($projection[0]['payload']), 'HALL_PROJECTION_AVAILABLE');
// Turn back OFF and prove no stale flag.
$payload['final_amount_rial']=false;$core->adminControls()->saveSettings($payload,$actor);$afterOff=$core->adminControls()->snapshot($actor);
$ok(($afterOff['settings']['final_amount_rial']??true)===false,'DISABLE_RIAL_SETTING_STORED');
$secret=bin2hex(random_bytes(32));$installation='r233-'.bin2hex(random_bytes(6));$actorProjection='user:'.$uid;
$cfg=\Sokna\Local\Core\Config::fromArray(['installation'=>['id'=>$installation],'public'=>['shared_secret'=>$secret]]);
$adapter=new \Sokna\Local\Relay\AccountPasswordRealtimeAdapter($cfg,$pdo,$core->identityRepository());
$key=hash_hkdf('sha256',$secret,SODIUM_CRYPTO_SECRETBOX_KEYBYTES,'sokna-public-self-password-change-v1',$installation);
$new='R233-unit-test-'.bin2hex(random_bytes(12));
$make=function(string $current,string $next,string $id)use($uid,$key):array{
    $now=time();$actor='user:'.$uid;$nonce=random_bytes(SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);
    $data=json_encode(['current'=>$current,'next'=>$next,'actor'=>$actor,'request_id'=>$id,'expires'=>$now+90],JSON_THROW_ON_ERROR);
    return ['kind'=>'account.password_change','request_id'=>$id,'actor_projection_id'=>$actor,'created_at'=>gmdate('c',$now),'expires_at'=>gmdate('c',$now+90),'payload'=>['nonce'=>base64_encode($nonce),'ciphertext'=>base64_encode(sodium_crypto_secretbox($data,$nonce,$key))]];
};
$requestId='qa-r233-'.bin2hex(random_bytes(10));$envelope=$make($old,$new,$requestId);
$j=json_encode($envelope,JSON_THROW_ON_ERROR);$ok(!str_contains($j,$old)&&!str_contains($j,$new),'PASSWORD_NOT_PRESENT_IN_QUEUE_ENVELOPE');
$receipt=$core->lanStaffRealtimeReceipts()->dispatchAtomic($installation,$envelope,fn()=> $adapter->dispatch($envelope));
$ok(($receipt['state']??'')==='committed'&&($receipt['result']['saved']??false)===true,'LOCAL_SIGNED_PAYLOAD_COMMITTED');
$q->execute([$uid]);$ok(password_verify($new,(string)$q->fetchColumn()),'LOCAL_PASSWORD_NEW_VALID');
$q2=$pdo->prepare("SELECT password_hash,credential_version,source_mode FROM remote_user_credentials WHERE user_id=?");$q2->execute([$uid]);$row=$q2->fetch(PDO::FETCH_ASSOC);
$ok(is_array($row)&&password_verify($new,(string)$row['password_hash'])&&$row['source_mode']==='local_password','REMOTE_CREDENTIAL_SYNCHRONIZED_ATOMICALLY');
$version=(int)$row['credential_version'];$replay=$core->lanStaffRealtimeReceipts()->dispatchAtomic($installation,$envelope,fn()=> $adapter->dispatch($envelope));
$ok(($replay['state']??'')==='committed'&&($replay['idempotent']??false)===true,'DUPLICATE_REQUEST_IDEMPOTENT');
$q2->execute([$uid]);$ok((int)$q2->fetch(PDO::FETCH_ASSOC)['credential_version']===$version,'REPLAY_DOES_NOT_INCREMENT_CREDENTIAL_VERSION');
$badEnvelope=$make($old,'R233-bad-other-pass-'.bin2hex(random_bytes(6)),'qa-r233-bad-'.bin2hex(random_bytes(6)));
$bad=$core->lanStaffRealtimeReceipts()->dispatchAtomic($installation,$badEnvelope,fn()=> $adapter->dispatch($badEnvelope));
$ok(($bad['state']??'')==='rejected','OLD_PASSWORD_REJECTED_AFTER_CHANGE');
$q->execute([$uid]);$ok(password_verify($new,(string)$q->fetchColumn()),'FAILED_CHANGE_PRESERVES_VALID_PASSWORD');
$wrongKey=$make($new,'R233-invalid-ciphertext','qa-r233-cipher-'.bin2hex(random_bytes(5)));$wrongKey['payload']['ciphertext']=base64_encode(random_bytes(60));
$wrong=$core->lanStaffRealtimeReceipts()->dispatchAtomic($installation,$wrongKey,fn()=> $adapter->dispatch($wrongKey));
$ok(($wrong['state']??'')==='rejected','INVALID_CIPHER_FAILS_CLOSED');
$logs=$pdo->prepare("SELECT details_json FROM audit_log WHERE actor_user_id=? AND action='account.password_changed' ORDER BY id DESC LIMIT 1");$logs->execute([$uid]);$details=(string)$logs->fetchColumn();
$ok($details!==''&&!str_contains($details,$old)&&!str_contains($details,$new),'AUDIT_WITHOUT_PASSWORD');
$rowQ=$pdo->prepare('SELECT result_json FROM lan_staff_realtime_receipts WHERE installation_id=? AND request_id=?');$rowQ->execute([$installation,$requestId]);$memo=(string)$rowQ->fetchColumn();
$ok(!str_contains($memo,$old)&&!str_contains($memo,$new),'RECEIPT_WITHOUT_PASSWORD');
$ok(!$pdo->inTransaction(),'NO_LEAKED_TRANSACTION');
echo "PASS_R233_REAL_MARIADB_".$checks."_CHECKS\n";